var e={id:`it-non-ho-mai-vita-e-universita`,title:`Non ho mai: vita e università`,language:`it`,spice:1,kind:`prompts`,games:[`never-have-i-ever`],items:[{text:`Non ho mai saltato una lezione per dormire.`},{text:`Non ho mai consegnato un compito un minuto prima della scadenza.`},{text:`Non ho mai studiato tutta la notte prima di un esame.`},{text:`Non ho mai finto di aver letto il libro.`},{text:`Non ho mai mangiato pasta in bianco per una settimana di fila.`},{text:`Non ho mai rifiutato un voto.`},{text:`Non ho mai copiato a un compito in classe.`},{text:`Non ho mai pianto in biblioteca.`},{text:`Non ho mai chiamato "mamma" una professoressa.`},{text:`Non ho mai dato la colpa di una puzza a qualcun altro.`},{text:`Non ho mai riciclato un regalo.`},{text:`Non ho mai silenziato per sempre il gruppo di famiglia.`},{text:`Non ho mai letto i messaggi di qualcuno da sopra la spalla.`},{text:`Non ho mai rubato cibo al coinquilino dal frigo.`},{text:`Non ho mai finto di stare male per saltare scuola o lavoro.`},{text:`Non ho mai mandato un vocale di più di cinque minuti.`},{text:`Non ho mai dormito durante una lezione.`},{text:`Non ho mai barato a carte con i parenti.`},{text:`Non ho mai gonfiato il curriculum.`},{text:`Non ho mai preso in prestito vestiti senza restituirli.`},{text:`Non ho mai avuto una cotta per un prof.`},{text:`Non ho mai tagliato i capelli da solo.`},{text:`Non ho mai visto una stagione intera in un giorno.`},{text:`Non ho mai scritto "sto arrivando" mentre ero ancora a letto.`},{text:`Non ho mai riso così tanto da grugnire.`},{text:`Non ho mai fatto finta di lavorare senza fare niente.`},{text:`Non ho mai speso tutto lo stipendio in un weekend.`},{text:`Non ho mai cantato al karaoke da sobrio.`},{text:`Non ho mai fatto l'imbucato a una festa.`},{text:`Non ho mai preso l'ultima fetta senza chiedere.`},{text:`Non ho mai origliato una conversazione in treno.`},{text:`Non ho mai cenato con i cereali.`},{text:`Non ho mai dimenticato un nome subito dopo averlo sentito.`},{text:`Non ho mai perso l'ultimo treno per tornare a casa.`},{text:`Non ho mai passato un weekend intero in pigiama.`},{text:`Non ho mai litigato con uno sconosciuto nei commenti.`},{text:`Non ho mai fatto finta di non essere in casa quando hanno suonato al citofono.`},{text:`Non ho mai detto ai miei che l'esame era andato meglio di com'era andato.`},{text:`Non ho mai fatto l'Interrail.`},{text:`Non ho mai dormito in stazione.`},{text:`Non ho mai passato settimane senza incrociare il mio coinquilino.`},{text:`Non ho mai preso un treno regionale con tre ore di ritardo.`}]};export{e as default};